concurrencyExample.source:
with Ada.Text_IO; use Ada.Text_IO;

procedure Concurrent_Hello is
   task Greeter;
   task body Greeter is
   begin
      Put_Line("Hello from a task!");
   end Greeter;
begin
   Put_Line("Hello from the main task!");
end Concurrent_Hello;

codeExample.source:
with Ada.Text_IO; use Ada.Text_IO;

procedure Hello is
begin
   Put_Line("Hello, World!");
end Hello;
